import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`course-demand`,heroTitle:`Validate your course idea in minutes`,heroSubtitle:`Perplexity Computer audits competitor courses, maps student pain points, and finds your best opportunity — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Searching the web for competitor courses and pricing`,`Analyzing reviews, forums, and creator communities for student pain points`,`Mapping saturated angles and underserved niches`,`Demand report with your best course opportunity — ready to act on`],generatingSteps:[`Searching competitor courses, reviews, and creator communities for your topic`,`Designing an agent to map student pain points, willingness to pay, and market gaps`,`Configuring saturation scoring and underserved niche detection across platforms`,`Setting up your demand report with prioritized opportunities and positioning angles`],featureSectionTitle:`From course idea to demand report`,featureCardTitles:[`Connects to your creator stack`,`Outputs you can build on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Google Drive, Airtable, Slack — Computer delivers your demand research straight into the tools you already use to plan and launch courses.`,`Competitor course breakdowns. Student pain point maps. Pricing benchmarks. Saturation scores. Underserved niche opportunities. A positioning brief for your best angle.`],capabilitySectionTitle:`Your market researcher, on autopilot`,capabilitySectionSubtitle:`Describe your course idea, step away, come back to a complete demand analysis.`,capabilityCards:[{title:`Competitor Audit`,description:`Computer can find and break down competing courses — pricing, curriculum, reviews, enrollment signals — so you see exactly what's already out there.`},{title:`Pain Point Mapping`,description:`Computer can scan student reviews, Reddit threads, and creator communities to surface the specific frustrations and gaps learners are willing to pay to solve.`},{title:`Niche Detection`,description:`Computer can score topic saturation and identify underserved angles — so you launch into demand, not into a crowded market.`},{title:`Connect Your Tools`,description:`Computer can push findings to Google Sheets, Notion, Airtable, and Slack — build workflows across your entire course planning stack.`},{title:`Remember & Learn`,description:`Computer can remember your niche, past research, and competitor landscape across sessions — so every analysis builds on what it already knows.`},{title:`Monitor & Alert`,description:`Computer can track new competitor launches, pricing changes, and trending student complaints — and flag shifts before you miss them.`}]});export{t as default};
